      {"id":"definitions-38-part-1","title":"HEART FAILURE","titleRuns":[{"t":"HEART","b":true},{"t":" "},{"t":"FAILURE","b":true}],"bookPages":[38],"blocks":[{"type":"heading","runs":[{"t":"DEFINITIONS"}],"bookPage":38},{"type":"paragraph","runs":[{"t":"Cardiomyopathy","b":true},{"t":" "},{"t":"(CM):","b":true},{"t":" disease of myocardium. This "},{"t":"can","i":true,"u":true},{"t":" lead to heart failure, but is "},{"t":"not","i":true,"u":true},{"t":" synonymous with heart failure"}],"style":"lead","bookPage":38},{"type":"list-item","runs":[{"t":"● Dilated CM: dilation or impaired contraction of one/both ventricles"}],"sourceIndent":0.02,"bookPage":38},{"type":"list-item","runs":[{"t":"◦ "},{"t":"Left","b":true},{"t":" "},{"t":"ventricular","b":true},{"t":" "},{"t":"internal","b":true},{"t":" "},{"t":"diameter","b":true},{"t":" "},{"t":"end","b":true},{"t":" "},{"t":"diastole","b":true},{"t":" "},{"t":"(","b":true},{"t":"LVIDd) >59mm males, >53mm females"}],"sourceIndent":36.03,"bookPage":38},{"type":"list-item","runs":[{"t":"● Restrictive CM: nondilated or small ventricle(s) with diastolic dysfunction"}],"sourceIndent":0.02,"bookPage":38},{"type":"list-item","runs":[{"t":"● Hypertrophic CM: increased LV mass, with nondilated, hypertrophied LV (IVS >15mm)"}],"sourceIndent":0.02,"bookPage":38},{"type":"list-item","runs":[{"t":"● Also: arrhythmogenic right ventricular cardiomyopathy/dysplasia (ARVC/D); unclassified CMs"}],"sourceIndent":0.02,"bookPage":38},{"type":"paragraph","runs":[{"t":"Heart","b":true},{"t":" "},{"t":"failure","b":true},{"t":" "},{"t":"(HF","b":true},{"t":"): clinical syndrome characterized by typical symptoms and signs that are caused by cardiac dysfunction. Hemodynamically, it is a failure to provide commensurate cardiac output to the body, or in which output is at cost of elevated cardiac filling pressures"}],"style":"lead","bookPage":38},{"type":"list-item","runs":[{"t":"● Heart failure with preserved ejection fraction (HFpEF) (EF≥ 50%) accounts for 40-50% of patients with HF"}],"sourceIndent":0.02,"bookPage":38},{"type":"list-item","runs":[{"t":"● Heart failure with reduced EF (HFrEF) (EF≤ 40%) accounts for 40-50% of patients with HF"}],"sourceIndent":0.02,"bookPage":38},{"type":"list-item","runs":[{"t":"● Heart failure with midrange EF (HFmrEF) (EF 41-49%) accounts for approximately 10-20% of patients with HF"}],"sourceIndent":0.02,"bookPage":38}]},
      {"id":"definitions-38-part-2","title":"KEY PHYSIOLOGY CONCEPTS","titleRuns":[{"t":"KEY","b":true,"u":true},{"t":" "},{"t":"PHYSIOLOGY","b":true,"u":true},{"t":" "},{"t":"CONCEPTS","b":true,"u":true}],"bookPages":[38],"blocks":[{"type":"paragraph","runs":[{"t":"Preload","b":true},{"t":": describes the myocardial wall stretch at the end of diastole"}],"style":"lead","bookPage":38},{"type":"list-item","runs":[{"t":"● Most accurate measure: LV end diastolic volume (LVEDV); rarely directly measured, can be approximated by some imaging methods or bedside hemodynamic assessments"}],"sourceIndent":0.02,"bookPage":38},{"type":"list-item","runs":[{"t":"◦ Closest proxy LV end-diastolic pressure (LVEDP) – can only be measured during LHC"}],"sourceIndent":36.03,"bookPage":38},{"type":"list-item","runs":[{"t":"● Closest estimate of LVEDP = left atrial pressure (LAP"},{"t":")","i":true},{"t":",","u":true},{"t":" "},{"t":"when","u":true},{"t":" "},{"t":"there","u":true},{"t":" "},{"t":"is","u":true},{"t":" "},{"t":"equal","u":true},{"t":" "},{"t":"pressure","u":true},{"t":" "},{"t":"gradient","u":true},{"t":" "},{"t":"from","u":true},{"t":" "},{"t":"ventricle","u":true},{"t":" "},{"t":"to","u":true},{"t":" "},{"t":"atrium","u":true}],"sourceIndent":0.02,"bookPage":38},{"type":"list-item","runs":[{"t":"◦ LAP best estimate: pulmonary capillary wedge pressure (PCWP), measured by RHC"}],"sourceIndent":36.03,"bookPage":38},{"type":"list-item","runs":[{"t":"● "},{"t":"AKA,","b":true},{"t":" "},{"t":"in","b":true},{"t":" "},{"t":"a","b":true},{"t":" "},{"t":"normal","b":true},{"t":" "},{"t":"heart","b":true},{"t":": LVEDV → LVEDP ≈ LAP ≈ PCWP"}],"sourceIndent":0.02,"bookPage":38},{"type":"list-item","runs":[{"t":"● In hearts with diastolic disease, ventricular volume and pressure may become uncoupled."}],"sourceIndent":0.02,"bookPage":38},{"type":"list-item","runs":[{"t":"◦ Increased LV stiffness (pericardial restriction or myo/endocardial), higher LVEDPs required to create same EDV"}],"sourceIndent":36.03,"bookPage":38},{"type":"paragraph","runs":[{"t":"Afterload","b":true},{"t":": describes the force opposing LV ejection"}],"style":"lead","bookPage":38},{"type":"list-item","runs":[{"t":"● Most accurately described as aortic impendence or elastance"}],"sourceIndent":0.02,"bookPage":38},{"type":"list-item","runs":[{"t":"● Afterload ≈ myocardial wall stress, which is defined according to Laplace’s Law"}],"sourceIndent":0.02,"bookPage":38},{"type":"figure","src":"assets/redbook-38-1.webp","width":573,"height":61,"label":"Laplace’s law for ventricular wall stress","bookPage":38},{"type":"list-item","runs":[{"t":"● Increased afterload → ↑ intraventricular pressure needed open the aortic valve → ↑ increased wall stress."}],"sourceIndent":0.02,"bookPage":38},{"type":"list-item","runs":[{"t":"◦ If exposed to chronically ↑ afterload → myocardial hypertrophy (increased thickness) to restore normal wall stress"}],"sourceIndent":36.03,"bookPage":38},{"type":"paragraph","runs":[{"t":"Contractility/Inotropy","b":true},{"t":": inherent capacity of the myocardium to contract independent of changes in preload or afterload."}],"style":"lead","bookPage":38},{"type":"list-item","runs":[{"t":"● ↑ contractile function a/w enhanced ventricular relaxation (lusitropy),"}],"sourceIndent":0.02,"bookPage":38},{"type":"list-item","runs":[{"t":"● Frank-Starling curve relates ventricular EDV (preload) to contractility"}],"sourceIndent":0.02,"bookPage":38},{"type":"list-item","runs":[{"t":"◦ ↑ in force of contraction as EDV ↑ with increasing sarcomere length and optimization of the overlap between"}],"sourceIndent":36.03,"bookPage":38},{"type":"paragraph","runs":[{"t":"actin + myosin filaments"}],"bookPage":38},{"type":"list-item","runs":[{"t":"◦ There is a limit to this optimization after which LVEDV / EDP will increase without additional increase in SV"}],"sourceIndent":36.03,"bookPage":38}]}
