      {"id":"catheter-associated-thrombosis-150-part-1","title":"Catheter-associated thrombosis","titleRuns":[{"t":"Catheter-associated","b":true,"u":true},{"t":" "},{"t":"thrombosis","b":true,"u":true}],"bookPages":[150],"blocks":[{"type":"paragraph","runs":[{"t":"Clinical","u":true},{"t":" "},{"t":"considerations","u":true}],"bookPage":150},{"type":"list-item","runs":[{"t":"● Incidence as high as 14-18%."}],"sourceIndent":0.02,"bookPage":150},{"type":"list-item","runs":[{"t":"● Duplex ultrasound is the diagnostic imaging modality of choice."}],"sourceIndent":0.02,"bookPage":150},{"type":"list-item","runs":[{"t":"● Current guidelines recommended that systemic anticoagulation be administered for at least three months after the catheter has been removed."}],"sourceIndent":0.02,"bookPage":150},{"type":"list-item","runs":[{"t":"● If central access is required, the CVC can remain in place as long as it is appropriately positioned and functioning correctly without evidence of infection."}],"sourceIndent":0.02,"bookPage":150},{"type":"list-item","runs":[{"t":"● If the catheter remains for > 3 months on therapeutic AC, LMWH prophylaxis is recommended until the line is removed.4"}],"sourceIndent":0.02,"bookPage":150}]}
