      {"id":"hypertensive-disorders-of-pregnancy-186-part-2","title":"Management","titleRuns":[{"t":"Management:","b":true}],"bookPages":[187],"blocks":[{"type":"paragraph","runs":[{"t":"Acute","b":true},{"t":" "},{"t":"severe","b":true},{"t":" "},{"t":"hypertension:","b":true},{"t":" reduce MAP by no more than 25% over 2h using "},{"t":"IV","u":true},{"t":" "},{"t":"labetalol","u":true},{"t":" "},{"t":"20","u":true},{"t":" "},{"t":"mg","u":true},{"t":" "},{"t":"over","u":true},{"t":" "},{"t":"2","u":true},{"t":" "},{"t":"minutes","u":true},{"t":" (hydralazine also OK but labetalol preferred), followed at 10 min interval doses of 20 to 80 mg up to max total cumulative dose of 300 mg if BP remains above target, "},{"t":"constant","u":true},{"t":" "},{"t":"infusion","u":true},{"t":" "},{"t":"can","u":true},{"t":" "},{"t":"be","u":true},{"t":" "},{"t":"used","u":true},{"t":" "},{"t":"instead","u":true},{"t":" "},{"t":"of","u":true},{"t":" "},{"t":"intermittent","u":true},{"t":" "},{"t":"therapy","u":true},{"t":".","b":true},{"t":" If labetalol alone ineffective ACOG recommends switching to "},{"t":"hydralazine","u":true},{"t":" (and vice versa). Alternative options include nicardipine and nifedipine. "},{"t":"If","b":true},{"t":" "},{"t":"PEC","b":true},{"t":" "},{"t":"or","b":true},{"t":" "},{"t":"Eclampsia","b":true},{"t":" → give IV mag sulfate in addition to anti-hypertensive medication. "},{"t":"Call","b":true},{"t":" "},{"t":"OB.","b":true},{"t":" "},{"t":"Chronic","b":true},{"t":" "},{"t":"HTN","b":true},{"t":" "},{"t":"→","b":true},{"t":" target is less than 140/90 mmHg "},{"t":"(","href":"https://www.nejm.org/doi/full/10.1056/NEJMoa2201295"},{"t":"CHAP","u":true,"href":"https://www.nejm.org/doi/full/10.1056/NEJMoa2201295"},{"t":" Trial Consortium, NEJM 2022; prior CHIPS 2015 trial suggested strict versus lax BP control were equal, but underpowered for clinical outcomes). "},{"t":"Meds:","b":true},{"t":" First line: labetalol and nifedipine."}],"style":"lead","bookPage":187},{"type":"paragraph","runs":[{"t":"Second line: hydralazine. Methyldopa less effective. If already on amlodipine or HCTZ, ok to continue. STOP ACEi, ARBs, MRA for teratogenicity."}],"style":"lead","bookPage":187},{"type":"paragraph","runs":[{"t":"Risk","b":true},{"t":" "},{"t":"reduction:","b":true},{"t":" ASA 81mg daily during 2T and 3T reduces PEC risk. USPTF Grade B recommendation for ASA after 12 weeks gestation (similar to ACOG recommendation for ASA)."}],"style":"lead","bookPage":187}]}
